// Goblin Anarchomancer
// status: ready
// Each spell you cast that's red or green costs {1} less to cast.
#[allow(unused_imports)] use cantrip_api::*;
#[allow(unused_variables)] fn ability_0_0_rule(q: &dyn Query, source: ObjectId, player: PlayerId, costed: Costed, targets: &[Target]) -> CostDelta { let asker = &Asker::new(source, q.controller(source)); let Costed::Spell(spell) = costed else { return CostDelta::NONE; }; if player == asker.controller && (q.chars(spell).colors.has(q.words(asker.source).color(Color::Red)) || q.chars(spell).colors.has(q.words(asker.source).color(Color::Green))) { CostDelta::less((1i64) as u8) } else { CostDelta::NONE } }

